    LONG nCandidateX;
    LONG nCandidateY;
    int nClampedDestY;
    if ((int)eSkill < 0) {
      return 0;
    }
    if ((int)eSkill >= sgptDataTable->nTxtSkillsCount) {
      return 0;
    }

