      nCandidateX = ptCandidatePos.y;
      pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
      pRoom = UNIT::Player::DRLGROOM_FindBetterNearbyRoom(pRoom, ptCandidatePos.x, nCandidateX);
